import json, glob, os
# scan all json files in workspace root/scripts/factors for factor-like docs with artifact info
hits=[]
for p in glob.glob('**/*.json', recursive=True):
    if os.path.getsize(p)>500000: continue
    try:
        d=json.load(open(p))
    except Exception:
        continue
    if isinstance(d,dict) and any(k in d for k in ('factor_id','signal','artifact','ic','icir')):
        hits.append((p, list(d.keys())[:12]))
for h in hits[:30]:
    print(h[0], h[1])
print("total factor-like files:", len(hits))
EOF

