import json, glob, os, re

files = sorted(glob.glob('factors/*.json'))
files = [f for f in files if not f.endswith('.bak')]

# Keep canonical: file with no timestamp pattern
def is_ts(b):
    return bool(re.search(r'\.\d{8}T\d{9}\.json$', b))

canon = {}
for f in files:
    b = os.path.basename(f)
    if is_ts(b):
        continue
    d = json.load(open(f))
    fid = d.get('factor_id')
    canon[fid] = f

print("Unique factor_ids (canonical files):", len(canon))
for fid, f in sorted(canon.items()):
    d = json.load(open(f))
    val = d.get('validation', {})
    adm = d.get('benchmark_admission', {})
    sel = adm.get('selected_metrics', {}) or {}
    m = val.get('metrics', {}) or {}
    by_year = val.get('by_year_ic1', {}) or {}
    tags = d.get('tags', [])
    tags_s = ','.join(tags) if isinstance(tags, list) else str(tags)
    yr_ic = {y: round(v.get('ic', float('nan')), 4) for y, v in by_year.items()}
    print(f"ID={fid}")
