python -c "
import json, glob
files = sorted(glob.glob('factors/*.json'))
files = [f for f in files if not f.endswith('.bak')]
# dedupe by factor_id keeping canonical (no timestamp)
seen = {}
for f in files:
    try:
        d = json.load(open(f))
        fid = d.get('factor_id', f)
        if fid not in seen:
            seen[fid] = (f, d)
        else:
            # prefer non-timestamped canonical
            if '.' not in f.split('/')[-1].replace('.json',''):
                seen[fid] = (f, d)
    except Exception as e:
        print('ERR', f, e)
print('unique factor_ids:', len(seen))
for fid, (f, d) in sorted(seen.items()):
    val = d.get('validation', {})
    tags = d.get('tags', {})
    print(fid, '| tags:', str(tags)[:90], '| val:', str(val)[:120])
"

