python - <<'EOF'
import json, glob, os

def load(f):
    with open(f) as fh:
        return json.load(fh)

# Build factor registry: dedupe by factor_id, prefer base files (no timestamp)
files = sorted([f for f in glob.glob('factors/*.json') if not f.endswith('.bak')])
registry = {}
for f in files:
    try:
        d = load(f)
        fid = d.get('factor_id')
        if not fid: continue
        base = not any(t in os.path.basename(f) for t in ['20260810T','20260811T'])
        if fid not in registry or base:
            registry[fid] = {'file': os.path.basename(f), 'data': d, 'is_base': base}
    except Exception as e:
