import json, glob, os
# Extract quality metadata from canonical factor files
files = [f for f in glob.glob('factors/*.json') if not f.endswith('.bak') and 'T' not in os.path.basename(f).split('.')[-2] if 'evicted' not in f]
# simpler: canonical = no timestamp pattern
import re
canon = [f for f in glob.glob('factors/*.json') if re.search(r'\.\d{8}T\d+\.json$', f) is None and f.endswith('.json') and 'evicted' not in f]
for f in sorted(canon):
    try:
        d = json.load(open(f))
        meta = d.get('metadata', d)
        # try common fields
        keys = ['factor_id','ic','icir','ic_mean','ic_ir','turnover','coverage','direction','status','category','quality_score']
        row = {k: meta.get(k) for k in keys if k in meta}
        if not row:
            row = {k: d.get(k) for k in keys if k in d}
        print(os.path.basename(f), '->', json.dumps(row)[:300])
    except Exception as e:
        print(os.path.basename(f), 'ERR', e)
EOF

